begin;
-- Card detail toolbar: a person may hide verbs they never use (ADR 0037). Hiding is display only.
create or replace function sill_private.validate_workspace_preferences(v jsonb) returns void language sql immutable security invoker set search_path='' as $$ select sill_private.validate_schema(v,'{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"singleKeyShortcuts":{"type":"boolean"},"sort":{"type":"string","enum":["priority","unread","time"]},"reduceTransparency":{"type":"boolean"},"stack":{"type":"boolean"},"fadeRead":{"type":"boolean"},"archiveAfter":{"type":"string","enum":["3d","7d","never"]},"floatTimely":{"type":"boolean"},"collapseOnFinish":{"type":"boolean"},"newHint":{"type":"string","enum":["away","off"]},"theme":{"type":"string","enum":["system","light","dark"]},"density":{"type":"string","enum":["compact","standard","roomy"]},"reduceMotion":{"type":"boolean"},"aiLocal":{"type":"boolean"},"onboarded":{"type":"boolean"},"hiddenActions":{"type":"array","maxItems":9,"items":{"type":"string","enum":["bookmark","tag","later","reply","open","join","snooze","download","dismiss"]}}},"additionalProperties":false}'::jsonb) $$;
create or replace function sill_private.workspace_preferences(v jsonb) returns jsonb language sql immutable security invoker set search_path='' as $$
 select '{"singleKeyShortcuts":true,"reduceTransparency":false,"sort":"priority","stack":true,"fadeRead":true,"archiveAfter":"7d","floatTimely":true,"collapseOnFinish":true,"newHint":"away","theme":"system","density":"standard","reduceMotion":false,"aiLocal":true,"onboarded":true,"hiddenActions":[]}'::jsonb||v
$$;
commit;
